const firstJson = $input.first().json;
const row = $('데이터 순회').item.json;

const emotionData = Array.isArray(firstJson)
  ? firstJson
  : $input.all().map(item => item.json);

if (!Array.isArray(emotionData) || emotionData.length === 0) {
  throw new Error('1차 감정분석 응답 오류: ' + JSON.stringify(firstJson).slice(0, 500));
}

const sorted = emotionData
  .filter(e => typeof e.score === 'number' && e.label)
  .sort((a, b) => b.score - a.score);

const rawEmotions = sorted
  .filter(e => e.score > 0.3)
  .slice(0, 10)
  .map(e => e.label);

const top1 = sorted[0]?.score ?? 0;
const top2 = sorted[1]?.score ?? 0;
const needs_review = rawEmotions.length === 0 || top1 < 0.75 || (top1 - top2) < 0.12;
const emotion_labels = rawEmotions.length > 0 ? rawEmotions : ['없음'];

return [{
  json: {
    ...row,
    raw_emotions: rawEmotions,
    emotion_labels,
    needs_review,
    top1_score: top1,
    score_gap: top1 - top2
  }
}];

const embedData = $input.first().json;
const row = $('1차 감정분석 파싱').item.json;

if (!Array.isArray(embedData?.embedding)) {
  throw new Error('임베딩 응답 오류: ' + JSON.stringify(embedData).slice(0, 500));
}

return [{
  json: {
    ...row,
    embedding: '[' + embedData.embedding.join(',') + ']'
  }
}];
